import ast, os, sys

TARGET = "DB_URL"

def is_target(node):
    return isinstance(node, ast.Constant) and node.value == TARGET

def reads_db_url(tree):
    """Return True if DB_URL env var is actually read (value used)."""
    for node in ast.walk(tree):
        # os.environ["DB_URL"]  /  environ["DB_URL"]  (load context only)
        if isinstance(node, ast.Subscript) and isinstance(node.ctx, ast.Load):
            if is_target(node.slice) and "environ" in ast.unparse(node.value):
                return True
        # os.environ.get("DB_URL"...) / environ.get / getenv / os.getenv
        if isinstance(node, ast.Call) and node.args and is_target(node.args[0]):
            func = ast.unparse(node.func)
            if func.endswith("get") or func.endswith("getenv") or func in ("getenv", "os.getenv"):
                return True
    return False

results = []
for root, dirs, files in os.walk("."):
    dirs[:] = [d for d in dirs if d not in (".git", "__pycache__")]
    for f in sorted(files):
        p = os.path.join(root, f)
        rel = os.path.relpath(p, ".")
        try:
            src = open(p, encoding="utf-8").read()
        except (UnicodeDecodeError, IsADirectoryError):
            continue
        if TARGET not in src:
            continue
        try:
            tree = ast.parse(src)
        except SyntaxError:
            print("SYNTAX ERROR:", rel, file=sys.stderr)
            continue
        if reads_db_url(tree):
            results.append(rel)

results.sort()
print("\n".join(results))
with open("answer.txt", "w", encoding="utf-8") as fh:
    fh.write("\n".join(results) + "\n")
print("count:", len(results), file=sys.stderr)

